"""Decode shipped original tracks and exercise genuine gesture/media lifecycle."""
from test_mobile_rendering import ROOT
from playwright.sync_api import sync_playwright
from http.server import ThreadingHTTPServer,SimpleHTTPRequestHandler
from functools import partial
import threading,json,hashlib
class Handler(SimpleHTTPRequestHandler):
 def log_message(self,*args):pass
server=ThreadingHTTPServer(('127.0.0.1',0),partial(Handler,directory=str(ROOT/'assets')));threading.Thread(target=server.serve_forever,daemon=True).start()
sha=hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest();errors=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.on('pageerror',lambda e:errors.append(str(e)));p.route('**/game.js',lambda r:r.fulfill(body=(ROOT/'assets/game.js').read_text().replace('// SOURCE: 99-instrumentation.js','window.__musicEval=s=>eval(s);\n// SOURCE: 99-instrumentation.js'),content_type='application/javascript'));p.goto(f'http://127.0.0.1:{server.server_port}/index.html');original_eval=p.evaluate;p.evaluate=lambda expr:original_eval('(s)=>{const v=__musicEval(s);return typeof v==="function"?v():v}',expr);assert p.evaluate('musicDecks.length')==0;p.locator('#newTown').click();p.locator('#pause').click();p.locator('#panelClose').click();p.wait_for_function('__musicEval("musicDecks.some(d=>!d.audio.paused&&d.audio.currentTime>0)")');p.locator('[data-panel=settings]').click();p.locator('#soundToggle').click();assert p.evaluate('musicDecks.some(d=>!d.audio.paused)');p.locator('#musicVolume').fill('25');assert p.evaluate('musicVolume')==.25;p.locator('#musicToggle').click();assert p.evaluate('musicDecks.every(d=>d.audio.paused)');p.locator('#musicToggle').click();p.wait_for_function('__musicEval("musicDecks.some(d=>!d.audio.paused)")');p.evaluate('__townArchive.suspend()');assert p.evaluate('musicDecks.every(d=>d.audio.paused)');p.evaluate('__townArchive.resume()');p.wait_for_function('__musicEval("musicDecks.some(d=>!d.audio.paused)")');p.locator('#musicNext').click();p.wait_for_function('__musicEval("!musicFade && musicDecks.length===1 && musicDecks[0].gain===1")');assert p.evaluate('musicDecks.length')==1;assert p.evaluate('musicDecks[0].gain')==1;index=p.evaluate('musicTrack');p.evaluate('()=>{const a=musicDecks[0].audio;Object.defineProperty(a,"currentTime",{configurable:true,value:MUSIC_TRACKS[musicTrack].seconds-3});a.dispatchEvent(new Event("timeupdate"))}');p.wait_for_function('__musicEval("musicTrack")!=='+str(index));assert p.evaluate('musicTrack')==(index+1)%3;assert p.evaluate('musicDecks.length')<=2;assert p.evaluate('musicError')==''
 decoded=p.evaluate('''async()=>{const ctx=new AudioContext(),rows=[];for(const t of MUSIC_TRACKS){const a=await ctx.decodeAudioData(await(await fetch('music/'+t.file+'.ogg')).arrayBuffer()),v=a.getChannelData(0);let energy=0,peak=0;for(let i=0;i<v.length;i+=32){energy+=v[i]*v[i];peak=Math.max(peak,Math.abs(v[i]))}rows.push({file:t.file,seconds:a.duration,channels:a.numberOfChannels,rms:Math.sqrt(energy/Math.ceil(v.length/32)),peak});}await ctx.close();return rows;}''');assert all(t['seconds']>170 and t['channels']==2 and .005<t['rms']<.3 and t['peak']<.99 for t in decoded),decoded
 p.reload();assert p.evaluate('musicVolume')==.25;assert p.evaluate('musicDecks.length')==0;assert not errors;b.close()
server.shutdown();server.server_close();assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==sha
out=ROOT/'reports/development-8.0';out.mkdir(exist_ok=True);(out/'music.json').write_text(json.dumps({'source_sha256':sha,'decoded':decoded,'realMediaPlayback':True,'subjectiveListening':False,'errors':errors},indent=2)+'\n');print('PASS original tracks decode/audible signal, real gesture play, independent mute/volume, host pause/resume, next piece and persisted preferences',decoded)
